noncompliant.code:
class User:
    def __init__(self):
        self.User = "John Doe"  # Field has same name as class

class Product:
    def __init__(self, name):
        self.Product = name  # Confusing field name

class Account:
    Account = "default"  # Class attribute with same name as class

compliant.code:
class User:
    def __init__(self):
        self.name = "John Doe"  # Clear, descriptive field name

class Product:
    def __init__(self, name):
        self.product_name = name  # Clear field name that differs from class

class Account:
    default_type = "savings"  # Clear class attribute name
